def read_tsv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle, delimiter="\t"))


def build_row(source: dict[str, str]) -> dict[str, str]:
    promotion_id = source["promotion_id"]
    if promotion_id in POSITIVE:
        item = POSITIVE[promotion_id]
        return {
            "promotion_id": promotion_id,
            "regulator_symbol": source["regulator_symbol"],
            "target_symbol": source["target_symbol"],
            "species_scope": source["species_scope"],
            "evidence_weight_tier": source["evidence_weight_tier"],
            "context_level_regulator": item["regulator"],
            "context_level_target": item["target"],
            "context_level_exact_pair": item["pair"],
            "context_evidence_scope": item["scope"],
            "context_evidence_basis": item["basis"],
            "context_evidence_citations": item["citations"],
            "context_promotion_lane": item["lane"],
            "sci_context_status": item["status"],
            "context_review_status": "adjudicated_positive_component_or_pair_context",
        }

    # C-tier records are explicitly source-table-only. They carry no
    # context-bearing model in the current packet, so complete the requested
    # conservative grading pass as L0/unverifiable rather than inferring a
    # context level from the TFLink citation or gene identities.
    if source.get("evidence_weight_tier", "").startswith("C_"):
        model = source.get("current_cell_or_model", "not recorded")
        return {
            "promotion_id": promotion_id,
            "regulator_symbol": source["regulator_symbol"],
            "target_symbol": source["target_symbol"],
            "species_scope": source["species_scope"],
            "evidence_weight_tier": source["evidence_weight_tier"],
            "context_level_regulator": CONTEXT_L0,
            "context_level_target": CONTEXT_L0,
            "context_level_exact_pair": CONTEXT_L0,
            "context_evidence_scope": CONTEXT_SCOPE_NO_QUALIFYING,
            "context_evidence_basis": (
                f"The C-tier record is source-table-only and the current record is "
                f"({model}); no authoritative CNS, spinal-cord-tissue, or SCI "
                "context can be verified from this evidence packet. The relationship "
                "is therefore resolved as context-unverifiable at L0 for this pass. "
                "This does not claim exhaustive literature absence and does not change "
                "the original C evidence tier."
            ),
            "context_evidence_citations": source.get("current_primary_citation", ""),
            "context_promotion_lane": CONTEXT_LANE_REVIEWED_NONE,
            "sci_context_status": SCI_CONTEXT_UNRESOLVED,
            "context_review_status": "resolved_unverifiable_context_in_current_packet",
        }

    model = source.get("current_cell_or_model", "not recorded")
    exact_pair_established = not model.startswith("not_established_for_exact_pair")
    level = CONTEXT_L1 if exact_pair_established else CONTEXT_L0
    scope = "exact_pair" if exact_pair_established else CONTEXT_SCOPE_NO_QUALIFYING
    lane = CONTEXT_LANE_NON_CNS if exact_pair_established else CONTEXT_LANE_REVIEWED_NONE
    basis = (
        f"The recorded exact-pair model ({model}) is non-CNS and does not provide CNS, "
        "spinal-cord-tissue, or SCI context. It therefore supports L1 non-CNS context "
        "for the exact pair, but no higher context level. This is a bounded screen "
        "result, not a claim of exhaustive literature absence."
        if exact_pair_established
        else (
            f"No exact-pair model was established in the current record ({model}); "
            "context is therefore L0 no evidence for the pair. This is a bounded "
            "screen result, not a claim of exhaustive literature absence."
        )
    )
    return {
        "promotion_id": promotion_id,
        "regulator_symbol": source["regulator_symbol"],
        "target_symbol": source["target_symbol"],
        "species_scope": source["species_scope"],
        "evidence_weight_tier": source["evidence_weight_tier"],
        "context_level_regulator": level,
        "context_level_target": level,
        "context_level_exact_pair": level,
        "context_evidence_scope": scope,
        "context_evidence_basis": basis,
        "context_evidence_citations": source.get("current_primary_citation", ""),
        "context_promotion_lane": lane,
        "sci_context_status": SCI_CONTEXT_LIMITED,
        "context_review_status": "adjudicated_no_qualifying_context_in_current_packet",
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, default=DEFAULT_INPUT)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    sources = [
        row for row in read_tsv(args.input.resolve())
        if row["evidence_weight_tier"].startswith(("A_", "B_", "C_"))
        or row["promotion_id"] in POSITIVE
    ]
    # One adjudication per promotion, even when the same evidence is routed to
    # more than one module.
    unique: dict[str, dict[str, str]] = {}
    for source in sources:
        unique.setdefault(source["promotion_id"], source)
    rows = [build_row(source) for source in unique.values()]
    rows.sort(key=lambda row: row["promotion_id"])
    args.output.resolve().parent.mkdir(parents=True, exist_ok=True)
    with args.output.resolve().open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS, delimiter="\t", lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
    print(f"wrote {len(rows)} context adjudications to {args.output.resolve()}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
